{"script":"() => {
  const repos = document.querySelectorAll('a[href*="/"][href$=" "]');
  const allLinks = Array.from(document.querySelectorAll('a'));
  const repoLinks = allLinks.filter(a => /^\/[^\/]+\/[^\/]+$/.test(a.getAttribute('href') || ''));

  const data = [];
  repoLinks.forEach(link => {
    const repoPath = link.getAttribute('href');
    const parent = link.closest('[class*="Box"], [class*="box"], div');
    const container = link.parentElement?.parentElement?.parentElement?.parentElement?.parentElement;
    if (container) {
      // Get the entire repo result block
      const fullText = container.textContent;
      const forkMatch = fullText.match(/(\d+\.?\d*[kK]?)\s*(fork)/i);
      const starMatch = fullText.match(/(\d+\.?\d*[kK]?)\s*(star)/i);
      data.push({
        repo: repoPath,
        forks: forkMatch ? forkMatch[1] : 'not found',
        stars: starMatch ? starMatch[1] : 'not found'
      });
    }
  });
  return JSON.stringify(data.slice(0, 15), null, 2);
}"}

